/* Worked readings keyed to the existing Field Manual exercise cursors (inclusive). */
window.FOF_LESSON_READINGS = {
  P1: [
    {"from": 0, "to": 0, "title": "從中央集結區讀這張地圖", "text": "找出 B0 上的第 1 排部、三個步兵班、1/LMG、1/AT 與迫擊砲前進觀測員。這七枚都要抵達第 3 列，三個班還要各走一欄。牌背在這裡代表集結區。B3 樹林下面另有一張丘陵。這一課沒有敵軍，也沒有回合上限，可以專心觀察每回合究竟有幾枚算子能走。"},
    {"from": 1, "to": 1, "title": "連部怎麼啟動地圖上的排部？", "text": "本課的連部在地圖外，演習假定它始終能聯絡第 1 排部。正式任務須確認雙方同區，或有可用的無線電、野戰電話等通訊方式。地圖外連部在這裡只下達「啟動第 1 排部」，不用替連部記點。\n把第 1 排的命令標記翻到「可用命令」。現在是已啟動的排部抽牌，讀第 30 號左上鋼盔內的大數字 3，把標記放在命令軌上半部的 3。"},
    {"from": 2, "to": 2, "title": "先看發令者與受令者在哪裡", "text": "第 1 排部可以指揮所屬或配屬單位。這些單位沒有自己的無線電或電話，得靠目視／口令。依規則 §4.3.1，一般須雙方都未受壓制，而且在同一張牌的同一區域。此刻排部和 1/1 班都在 B0 的掩蔽外，符合條件。\n花 1 點執行「移至相鄰牌」（§4.2.2a）。1/1 班可以斜走到左前方 A1，抵達後標記暴露，排部的命令從 3 降到 2。"},
    {"from": 3, "to": 4, "title": "一枚班離開牌，下一道命令還能給誰？", "text": "每下一道命令，重新查看受令者此刻的位置。1/1 班已離開 B0，但 2/1 班和 3/1 班仍與排部同區，兩班各可用 1 點移到相鄰牌，每班走完都要標記暴露。花完第三點，就把第 1 排的命令標記翻回「啟動完成」並放入零點格。"},
    {"from": 5, "to": 5, "title": "第 25 號要讀哪個數字？", "text": "第 1 排部本回合已經啟動，不能再抽一次排部主動命令。現在輪到「一般主動行動」，連內的單位可以用這些點自行行動。\n所有主動行動抽牌都讀左上角鋼盔下方的小數字。第 25 號的大數字是 3，小數字是 2。依流程輔助表，只有一個排參與時，一般主動命令點減半並捨去小數，所以 2 ÷ 2 ＝ 1。這 1 點記在一般主動欄。"},
    {"from": 6, "to": 6, "title": "1/AT 移動後，暴露標記怎麼放？", "text": "用剛才算出的 1 點一般主動，讓 1/AT 巴祖卡組從 B0 斜走到左前方開闊田野 A1。這個點讓單位自行行動，無須排部傳令，但跨牌移動仍會暴露。\nA1 上的 1/1 班也已暴露。實體棋桌上可以把兩枚算子並排，各放一枚暴露標記，也可以疊放共用一枚。此處兩者都在田野的掩蔽外，效果相同。移入較佳掩蔽或野戰工事時，算子是否在該掩蔽標記下才有規則意義。"},
    {"from": 7, "to": 7, "title": "清理時為什麼要拿走暴露？", "text": "暴露既會帶來不利的戰鬥修正，也限制單位再次執行移至相鄰牌。這一課沒有敵軍、潛在接敵或車輛，所以本回合後續各階段都沒有要結算的對象。到清理階段才移除暴露，把零點的第 1 排命令標記移回待用格，並推進回合。"},
    {"from": 8, "to": 10, "title": "查看命令軌，再決定誰先走", "text": "新回合重新由地圖外連部啟動第 1 排部。第 24 號的鋼盔給 4 點。1/LMG 和觀測員都還在 B0，排部可以先後命令它們各走一張牌。即使目的不同，只要下令當下符合通訊條件，兩道命令就都有效。"},
    {"from": 11, "to": 12, "title": "排部移動會改變下一道命令的範圍", "text": "排部能用自己的 1 點命令自己移動。它進入 B1 時也要標記暴露，可與已暴露的觀測員共用標記。2/1 班在 B1 尚未移動，現在才與排部同區。排部雖已暴露，仍可花最後 1 點命令該班進入 B2。"},
    {"from": 13, "to": 15, "title": "分開的步兵班如何取得行動？", "text": "1/1 班在 A1，排部在 B1，兩者無法用本課的目視／口令跨牌下令。第 27 號的小數字為 2，單排一般主動得到 1 點，1/1 班便能自行移入 A2 果園。這回合的排部點數已花完，清理時只需解除暴露、重設標記。"},
    {"from": 16, "to": 18, "title": "四點命令如何跟著排部的位置使用？", "text": "第 11 號鋼盔給 4 點。觀測員與排部都在 B1，先讓觀測員去 B2，排部還能用下一點向右到 C1。若先把排部移開，留在 B1 的觀測員就超出這次的目視／口令範圍。"},
    {"from": 19, "to": 20, "title": "同牌上的兩枚單位，各要幾點？", "text": "排部在 C1 時可以向同區的 3/1 班和 1/LMG 下令。這裡選用兩次單位移動，所以各花 1 點，合計 2 點。兩枚算子都到 C2 且暴露，在同一枚暴露標記下疊放也能記下同樣的狀態。"},
    {"from": 21, "to": 23, "title": "小數要在哪一步捨去？", "text": "第 16 號的小數字是 3。單排一般主動先減半得 1.5，再捨去小數，實得 1 點。在 A1 的 1/AT 已與排部分開，可以用這一點去 A2。到了清理階段才解除本回合的暴露。"},
    {"from": 24, "to": 27, "title": "有命令剩下，為什麼停在這裡？", "text": "第 23 號鋼盔給 4 點。排部從 C1 斜走到 B2，與觀測員和 2/1 班會合，再分別花一點讓它們走到 B3。三次移動共花 3 點。排部已暴露，不能再跨牌，自己牌上也沒有可移動的受令者，所以還有 1 點可儲存。"},
    {"from": 28, "to": 30, "title": "排部存的命令和一般主動要分開記", "text": "第 1 排標記翻至「啟動完成」並移到下半部的儲存區 1 格。日間、一般經驗的指揮部最多可存 6 點。接著另抽第 13 號，一般主動取小數字 3，減半捨去後的 1 點給 1/1 班前進。一般主動點不能帶到下回合。清理時把排部存下的 1 點移回上半部。"},
    {"from": 31, "to": 34, "title": "把上回合的儲存加入新抽的命令", "text": "第 3 號鋼盔內是 5。第 1 排原已儲存 1 點，這次合計 6 點。排部去 C2，接著命令 3/1 班和 1/LMG 先後去 C3。每次花 1 點，留下 3 點可存。這也解釋了命令軌為什麼要分成可用與儲存兩區。"},
    {"from": 35, "to": 37, "title": "班都到齊了，演習為什麼還沒結束？", "text": "第 18 號的小數字 2 可換得 1 點一般主動。1/AT 可以自己從 A2 走到 A3。此時三個班各佔一欄，七枚中已有六枚在第 3 列。排部仍在 C2 且已暴露，要等清理移除暴露，下回合才能再移動。"},
    {"from": 38, "to": 39, "title": "用最後一枚算子核對完成條件", "text": "手冊指定第 6 回合讓排部進第 3 列，沒有指定這次的牌號。網頁選用第 47 號。鋼盔的 1 點加上儲存的 3 點，共 4 點。花 1 點把排部從 C2 移入 C3，再數一次七枚算子和三個班的位置。"},
  ],
  P2: [
    {"from": 0, "to": 0, "title": "已發現的陣地如何設置", "text": "B3 樹林上的德軍輕機槍已被發現，放在散兵坑下。這一課把遭遇的位置固定，直接練習視線、火力量和命中效果。地圖與集結區不能互射，離開集結區後才需要檢查射擊。"},
    {"from": 1, "to": 4, "title": "排部在什麼時候能下令？", "text": "第 35 號左上大數字是 3，因為排部已被連部啟動。三枚接受命令的算子都從排部所在的 B0 起步，每移到一張相鄰牌就扣 1 點並標記暴露。第 1 回合走到的兩翼田野都在 B3 的視線外。"},
    {"from": 5, "to": 6, "title": "最後一枚算子用哪一條命令軌？", "text": "排部的 3 點已花完，而且已啟動的排部不能再抽自己的主動命令。一般主動是另一個時段，讀第 18 號左上小數字 2，因只有一個排參加而減半，得到的 1 點由 3/1 自行移動。"},
    {"from": 7, "to": 8, "title": "第一次敵軍活動為何不產生新遭遇？", "text": "從敵軍防禦活動優先表最上方開始，採第一個符合現況的項目。這課的特殊規則把「移除單位，放 PC」改成「不採取行動」，所以德軍留在原牌。友軍移動產生的暴露留到清理才拿掉。"},
    {"from": 9, "to": 11, "title": "移動讓兩枚算子開始交戰", "text": "排部先走到 C1，才能對同牌的 1/1 下目視／口令。1/1 進入 C2 後，與已發現的 B3 敵軍彼此看得見、也在相對應的射程內，立即放雙方的主要射向（PDF）與火力量（VOF）。放標記不再花命令點，單位受什麼效果則等戰鬥步驟判定。"},
    {"from": 12, "to": 14, "title": "第二個來向怎麼記？", "text": "A2 的 1/LMG 與 C2 的 1/1 從不同牌向 B3 提供火力。B3 只用較強的一種基本 VOF，另加交叉火力 −1。德軍原有主要射向仍朝 C2，直到敵軍活動查到「主要射向以外來火」，第 32 號底部 R#4＝3 才把它改向 A2。"},
    {"from": 15, "to": 15, "title": "先算 B3 的淨戰鬥修正", "text": "把同一個目標適用的數字相加。樹林 +2、散兵坑 +1、自動武器 −1、交叉火力 −1，得到 +1。沿第 20 號牌的 +1 列讀到 PIN，給德軍壓制。本步驟視為同時發生，先維持它對 A2 的火力量。"},
    {"from": 16, "to": 18, "title": "HIT 後為什麼還要抽一張？", "text": "A2 的果園 +1、自動武器 −1、暴露 −2，合計 −2。先用第 49 號判定 HIT，再用第 14 號讀目標的「一般」經驗欄。LC 有兩個字母，但 1/LMG 只有一階，只套用 L。換成擔架組並放壓制，暴露等清理才移除。"},
    {"from": 19, "to": 23, "title": "保留點數與傳令位置分開看", "text": "第 45 號啟動值 2，加上排部上回合留的 2 點，共可用 4 點。排部離開 C1 前先命令同牌的 1/AT，回到 B0 後才能叫觀測員和 2/1 行動。B1 新出現的主要射向使 B3 再次受到兩個方向的火力。"},
    {"from": 24, "to": 25, "title": "兩張檢定牌都要看完", "text": "觀測員可花一般主動點對視線內的 B3 嘗試本課的地圖外支援。每次抽兩張找爆炸圖示。第一張已成功仍要翻第二張，後牌可能有短彈。本次成功後放「待發 −3」及集中目標，後者記住同一支援對象的目標牌。"},
    {"from": 26, "to": 28, "title": "先翻來襲，才檢查誰解除壓制", "text": "受壓制德軍查有限行動小組／受壓制表，本例沒有領導者，R#4＝2 是不採取行動。待發在火力任務更新時翻成來襲，阻斷 B3 向外的視線，A2 原有 VOF 因而消失。此後的壓制恢復才會自動移除 A2 擔架組的壓制。"},
    {"from": 29, "to": 31, "title": "地形上的爆炸圖示也算修正", "text": "B3 樹林 +2、牌上爆炸圖示 −1、散兵坑 +1、壓制 +1、來襲 −3、交叉火力 −1，總計 −1。第 31 號的 −1 欄為 HIT，第 40 號一般欄的 P 把這一階換成癱瘓組。來襲會留到下回合火力任務更新。"},
    {"from": 32, "to": 34, "title": "移動後重新看主要射向", "text": "排部先就位，再命令同牌的 2/1 離開 B1，原來從 B1 指向 B3 的方向隨之消失。從新位置 A2 再檢查視線，仍能看見已發現的敵軍，和 C2 再度構成兩個來向。排部抽得 3 點、使用 2 點，另存 1 點。"},
    {"from": 35, "to": 36, "title": "重整能恢復到哪一級？", "text": "擔架組在 A2 已不受 VOF，用 1 點一般主動進行重整，自動升成火力組。升級順序是癱瘓組、擔架組、火力組、突擊組，每升一級是一種行動。原來的專用輕機槍算子無法藉此取回。"},
    {"from": 37, "to": 39, "title": "敵軍離場後，哪些標記仍然有效？", "text": "第 48 號底部 R#4＝4，B3 的受壓制癱瘓組按表後退，朝地圖頂端再無地形牌，因此離場。來襲按火力任務更新時機移除，友軍的主要射向仍需另行處理。手冊在這裡交由玩家續玩。"},
    {"from": 40, "to": 42, "title": "續局先解除一個方向的友軍火力", "text": "這是網頁選的一種續局。第 12 號大數字 4 加排部儲存的 1 點，共 5 點。排部趕到 C2 後命令同牌單位停火，來自 C2 的主要射向消失，B3 於是少一個方向，交叉火力修正先拿掉。"},
    {"from": 43, "to": 45, "title": "兩點一般主動如何完成目標？", "text": "第 2 號的小數字 4 在單排任務減半，剩 2 點。第一點讓 A2 停火，B3 最後一個基本 VOF 才移除。第二點由 1/1 進入 B3。目標同時要求敵軍已清除與有友軍占據中央樹林，德軍退場時還差後者。"},
  ],
  P3: [
    {"from": 0, "to": 1, "title": "活動程度開始影響命令點", "text": "第一列放 A 級潛在接敵（PC）標記，第二列放 B 級。地圖目前沒有 VOF、主要射向或已發現敵軍，活動為「無接敵」。排部第 1 號牌大數字 6 加活動修正 1，共 7 點。本例排部本回合最多花 6 點。"},
    {"from": 2, "to": 4, "title": "踏進 PC 牌，為什麼先不翻標記？", "text": "三個班各自從排部所在的集結區移到相鄰牌，每班花 1 點並暴露。PC 要到雙方戰鬥階段的潛在接敵評估才按順序判定。此時排部 7 點扣 3 點，可存 4 點。"},
    {"from": 5, "to": 6, "title": "找掩蔽要看地形牌的哪個數字？", "text": "2/1 本來就享有地形牌印的掩蔽與隱蔽值。這次花點是嘗試尋找額外的掩蔽標記。開闊田野牌底中央寫抽 2 張，左下是最多 1 枚額外掩蔽。兩張都沒有 Cover，保留原本地形值。"},
    {"from": 7, "to": 9, "title": "先決定是哪張牌，再決定發生什麼事", "text": "三張有友軍的 A 級 PC 平手，把它們依序編號，讀牌底 RAND 3 選 B1。無接敵時，A 級自動發生接敵，直接查組合。第 6 號 RAND 4＝1 是觸發牌上的來襲 −3。此時已過火力任務更新，所以標記直接用生效面。"},
    {"from": 10, "to": 13, "title": "同一列的三枚 PC，抽牌數為何不同？", "text": "每結算一枚就重看整張地圖。B1 受 VOF 後升為接敵，C1 的 A 級改抽 7 張。C2 出現未發現敵軍並使 C1 也受 VOF 後，兩張有人牌受火，升為交戰，A1 的 A 級只抽 5 張。找 Contact 要翻足有效張數，重洗牌不占張數。"},
    {"from": 14, "to": 16, "title": "命中後拆分算子，留意總兵力階", "text": "B1 地形 0、來襲 −3、暴露 −2，共 −5，超過表底時查 −4。F 讓三階班拆成兩階班與一階火力組。C1 的 PL 則產生癱瘓組、擔架組和剩下的一階火力組。兩張牌各仍有三階，拆出的各單位都受壓制，只有 C 的效果才是傷亡。"},
    {"from": 17, "to": 19, "title": "滲透成功與失敗各改變什麼？", "text": "排部得啟動點 3 加前次所存 4 點。B1 還有來襲 VOF，所以 1/LMG 符合滲透的起點或目的牌須有火力量這項條件。兩張中有 Infiltrate 就移動且免暴露。若都沒有，仍移到目的牌但要標記暴露。"},
    {"from": 20, "to": 21, "title": "同樣是移動，為什麼這次花兩點？", "text": "全排移至相鄰牌是一次花 2 點，由排部與同牌、能通訊、符合移動資格的所屬單位一起走。不同掩蔽區域、受壓制或已暴露者不能同行。排部、1/AT 和觀測員進 A1 都暴露，排部隨即能對原在 A1 的 1/1 再下個別命令。"},
    {"from": 22, "to": 23, "title": "發現嘗試怎麼算到兩張？", "text": "第 15 號小數字 3，單排減半捨去小數得 1 點。先從 1/1 所在牌確認能透過中間田野的兩道白邊看見目標，再算發現牌數。基本 2 張、目標在掩蔽下 −1、目標為 A 級 +1，合計 2 張找準星。發現是唯一保證至少抽一張的嘗試。"},
    {"from": 24, "to": 26, "title": "續局從尚未結算的階段接起來", "text": "手冊在第 2 回合友軍指揮之後把棋局交給玩家。這條網頁示例先移除上回合的來襲，再按當下活動程度處理 A2 的 PC B。壓制恢復看單位是否仍受 VOF。仍受火者要分別抽戰鬥結果，不能因為在同牌就共用一張。"},
    {"from": 27, "to": 29, "title": "儲存上限和當回合可用命令是兩個數字", "text": "本例排部新抽 4 點，加原存 3 點，命令軌暫有 7 點。花 1 點讓同牌 1/AT 進 B2，餘 6 點正好達白晝、一般經驗排部的儲存上限。一般主動另讀第 2 號的小數字，4 減半得 2 點。"},
    {"from": 30, "to": 31, "title": "算子已進目標牌，還缺什麼？", "text": "用一般主動點時，兩個遠離排部的班可以各自行動。進入敵軍所在的 C2 後要重新整理牌外和同牌火力。1/1 也可移入 B3。即使丘陵上已有友軍，仍要評估其餘 PC 並清除敵軍。"},
    {"from": 32, "to": 34, "title": "同牌交戰，活動程度一定最高嗎？", "text": "只算「有人且受 VOF」的地形牌數，一張牌上擺了多枚算子仍只算一張。這個續局只剩 C2 一張符合，活動為接敵。激烈交戰還需要至少另一張有人牌也受火。先用 RAND 2 排定順序，再逐張查 B 級，每處 5 張。"},
    {"from": 35, "to": 36, "title": "最後核對三個條件", "text": "同在 C2 的雙方要各查一次戰鬥結果。PIN 保留原單位與兵力階，只加壓制。一階敵軍在 HIT 後讀 C 才換成傷亡。六枚 PC 全部結算、敵軍作戰算子清除、B3 有友軍，才完成這次演習。"},
  ],
  C1: [
    {"from": 0, "to": 1, "title": "設置公開，為什麼還要放未發現？", "text": "第 36 頁分別用 R#2、R#3、R#4 決定掩體所在欄、掩體朝向、散兵坑所在欄。玩家因此能放好算子，連隊在遊戲中仍須做發現嘗試才能與這些已設置的敵軍交戰。這課沒有 PC，也不用追蹤活動程度。"},
    {"from": 2, "to": 4, "title": "連部與排部各從哪裡取得命令點？", "text": "這課假設連部一直能與兩個排部及迫擊砲分隊通訊。連部被營部啟動後抽第 49 號，只有 1 點，拿來啟動第 1 排。第 1 排才以自己的第 31 號鋼盔取得 3 點，第 2 排須等自己的主動時段。"},
    {"from": 5, "to": 6, "title": "分離突擊組以後要另下移動令", "text": "用 1 點把三階 1/1 班分成兩階班和一階突擊組，兩枚合計仍是三階。新算子也還在 B0。再花 1 點才把突擊組移到 B1 並標記暴露，餘下 1 點可由第 1 排保留。"},
    {"from": 7, "to": 10, "title": "未啟動的排部與一般主動各抽一次", "text": "第 2 排未啟動，可讀第 36 號左上小數字，得 1 點。之後全連另抽一般主動，本次有兩個排，小數字 1 可全數使用。用它發現 C2 時，基本 2 張、目標掩蔽 −1、目標地形值 0 加 1、A 級再加 1，共抽 3 張找準星。"},
    {"from": 11, "to": 13, "title": "兩場戰鬥同時，先放的壓制不會改變另一場", "text": "敵軍活動先查優先表，R#4＝1 讓 C2 維持原來方向。戰鬥時 C2 以地形 0、散兵坑 +1、自動武器 −1 查 0。B1 以沼澤 +1、暴露 −2、自動武器 −1 查 −2。兩邊都結算完，才依新壓制和傷亡更新火力，傷亡不能成為合法目標。"},
    {"from": 14, "to": 16, "title": "兩個排部都受啟動時，先後可選", "text": "連部這回合有 3 點，2 點分別啟動兩排，最後 1 點把自己的 C0 指定為傷亡收集點（CCP）。集結區也能設 CCP，到回合末才登記該處傷亡已疏散。玩家可決定先處理哪個已啟動排部，手冊先選第 2 排。"},
    {"from": 17, "to": 20, "title": "三次滲透各自抽兩張，失敗仍移動", "text": "滲透是一次移動嘗試，起點或目的地須有 VOF。本例觀測員、排部、2/LMG 各使用一個命令，分別檢查自己的兩張牌，成功可免暴露。這三組都沒翻到 Infiltrate，所以三枚算子仍到目的地，各自標記暴露。"},
    {"from": 21, "to": 23, "title": "支援待發期間，原有射向仍要追蹤", "text": "第 2 排最後 1 點由同牌觀測員嘗試支援。兩張中有爆炸，C2 先放待發 −3。集中目標記錄這次目標，若持續對同牌呼叫同種支援，有助下次嘗試。輪到第 1 排時可用大數字 3 加儲存 1，共 4 點。"},
    {"from": 24, "to": 26, "title": "傷亡如何隨單位走？", "text": "1/1、觀測員和排部先後移到 B1，排部現在可向同牌 1/1 下令拾取傷亡。以傷亡算子置於 1/1 下方表示攜行，或登記在指揮顯示板。拾取會造成暴露，但 1/1 已暴露，效果不再疊加。"},
    {"from": 27, "to": 29, "title": "看見目標與改變主要射向是兩件事", "text": "第 34 號小數字 2。第一點移動迫擊砲分隊，這種分隊暴露時沒有基本射擊。第二點讓 2/LMG 嘗試發現自己的主要射向以外的 C3。基本 2 張減掩蔽 1 張，A/S 不提供 A 級加成。即使成功，原有主要射向也不會自動轉向。"},
    {"from": 30, "to": 32, "title": "敵軍活動與火力任務更新依序進行", "text": "先用 R#2 決定兩張敵軍牌的活動順序，再按各自狀態選表。C2 的待發要等火力任務更新才翻成來襲，這時它失去向外視線。算 C2 的戰鬥結果只取最強 VOF −3，另加散兵坑 +1、受壓制 +1、交叉火力 −1，合計 −2。"},
    {"from": 33, "to": 34, "title": "溝渠上兩個地形值用哪一個？", "text": "只有全部方向的火力都經白邊進入時才用較小的值。本例來向經溝渠的深綠斜邊，所以取 +2，與暴露 −2 抵銷，輕兵器 0，查第 26 號的 0 欄。清理移除暴露，壓制須留在對應算子上。"},
    {"from": 35, "to": 37, "title": "從手冊指定局面接續後送與重整", "text": "手冊的固定牌序到第 2 回合為止。這條網頁續局練習它留下的兩個問題。已攜行的傷亡跟 1/1 到 C0，抵達 CCP 可自動放下。D2 的 2/LMG 還受 VOF，這時嘗試移除壓制須抽牌找重整圖示。"},
    {"from": 38, "to": 39, "title": "傷亡和疏散是兩次不同的登記", "text": "C2 的一階癱瘓組仍是單位，要另做戰鬥判定。命中後查一般欄的 C，才換成傷亡。C0 的友軍傷亡已經抵達 CCP，回合末再把它從棋桌移出，登記後送。"},
    {"from": 40, "to": 43, "title": "一張牌上的發現與命中怎麼分？", "text": "同牌一枚敵軍被發現，該牌其餘敵軍也算已發現，但戰鬥效果仍須逐枚結算。B3 的戰壕班和掩體小組各抽自己的結果，HIT 後再看各自兵力階及經驗欄。三階班抽 CC 會剩一階，不能把整個班都算成傷亡。"},
    {"from": 44, "to": 45, "title": "重洗牌在這次抽牌結束後才處理", "text": "第 51 號不算一般主動所需的一張，先從原牌堆再翻一張得點，然後將整副牌洗勻。C3 的三階班若受 CC，同樣還要留下末階算子。這一階仍計入任務目標。"},
    {"from": 46, "to": 48, "title": "回到演習目標，核對剩餘作戰單位", "text": "兩張牌的算子分開結算。C3 的修正是地形 +2、戰壕 +2、受壓制 +1、A 級 VOF −1，合為 +4。第 49 號仍可命中。最後兩枚末階算子轉為傷亡後，原來八階已全部清除。十回合是期限，達標即可結束。"},
  ],
  C2: [
    {"from": 0, "to": 1, "title": "七種組合共用同一批備用算子", "text": "第 1 列四枚 PC A、第 2 列四枚 PC B 先入場，德軍留在供應區。抽到組合時得先確認配件夠、位置合法、能影響觸發牌。若所需算子已用完，重抽可放的組合，全無可放才算無接敵。標記和作戰算子適用的放置限制不同。"},
    {"from": 2, "to": 5, "title": "活動修正何時加在排部抽牌上？", "text": "手冊給設置與目標，接下來是網頁示例牌序。起始無接敵，所以連部與第 1 排的啟動抽牌各在大數字上加 1。連部每啟動一個排部花 1 點。輪到第 1 排時，班從與排部同區的 B0 出發，移入 PC 牌先標記暴露。"},
    {"from": 6, "to": 9, "title": "第 2 排的點數不能拿給第 1 排使用", "text": "第 22 號大數字 4 加無接敵 1，第 2 排有 5 點，可指揮在 D0 的所屬單位。兩排都啟動過，直接進一般主動。一般主動是全連另外抽的小數字，在本連級任務不減半，也不加無接敵修正。"},
    {"from": 10, "to": 12, "title": "用兩種隨機欄處理第一枚 PC", "text": "同級 PC 的順序與接敵後的組合是兩次不同判讀。四個候選先看 R#4 選 A1。無接敵時 PC A 自動接敵，再按第 48 頁 A 級表看 R#6。組合 1 直接在 A1 放生效來襲 −4，表上沒列觀測員，無須加算子。"},
    {"from": 13, "to": 15, "title": "第一枚處理完，下一枚就可能改抽七張", "text": "A1 上有友軍，來襲 VOF 讓活動立即升為接敵。因此接下來的 A 級不再自動，改為抽 7 張找 Contact。用來決定先後的那張只讀 RAND，其他圖示不作數。"},
    {"from": 16, "to": 18, "title": "一枚 PC 移除後，還要不要結算戰鬥？", "text": "每個待查位置都要完成自己的 7 張。未見 Contact，移除該處 PC 而不放組合。這不會消去別張牌先前放置的 VOF。A1 的友軍仍須結算來襲，本例第 1 號是 MISS，來襲仍留到下回合的火力任務更新。"},
    {"from": 19, "to": 22, "title": "命令點足夠，為何無法隔牌調動步兵班？", "text": "兩個排部仍在集結區，四個步兵班卻都已跨牌，而且沒有各自的通訊裝備。啟動排部取得點數，仍須另檢查它能否與受令班通訊。本例選擇放棄排部點數，等一般主動讓分散的班分別自行行動。"},
    {"from": 23, "to": 27, "title": "兩個排參與，不套用單排的減半", "text": "第 3 號牌左上小數字 4，連級演習可用全部 4 點，每個班自行花 1 點跨一張牌、標記暴露。四個班進入第 2 列後，B 級 PC 和友軍同牌，仍等到潛在接敵評估依序檢查。"},
    {"from": 28, "to": 30, "title": "為何第一枚 B 級又是自動？", "text": "火力任務更新先於 PC 評估。A1 的來襲一移除，棋桌已無 VOF、主要射向或已發現敵軍，活動回到無接敵。首枚 B 級自動接敵，改讀組合表 B 欄的 R#7。結果 2 在 A2 放一個已發現的小組。"},
    {"from": 31, "to": 35, "title": "重算活動時數地形牌，不數算子", "text": "A2 上敵我同牌，仍只算一張有人牌受 VOF，活動是接敵。剩餘 B 級 PC 因而各抽 5 張找 Contact。同級有多枚就為剩餘位置重新編號，最後一枚無須再抽順序。每次完成後移除該處 PC。"},
    {"from": 36, "to": 37, "title": "同牌雙方各抽，最後清點在場敵軍", "text": "A2 上友軍與敵軍各自判定，先後順序不改變同時結算原則。先以卡上戰鬥結果判 HIT，再按目標經驗欄的 C 將一階小組換為傷亡。檢查八枚 PC 已全部結算、在場作戰敵軍已清除，供應區和傷亡均不計入。"},
  ],
  C3: [
    {"from": 0, "to": 3, "title": "先看指揮顯示板上的兩個網路", "text": "連部同時持有營網 SCR300 與連網 SCR536，各接不同的對象。兩個排部和迫擊砲分隊各拿連網 SCR536。普通步兵班沒有配發。之後檢查命令能否傳到時，可回來核對是哪枚算子持有哪一部。"},
    {"from": 4, "to": 5, "title": "丘陵與掩蔽標記，對連網各管什麼？", "text": "本課的 SCR536 要求兩端有視線，圖中的丘陵可以讓聯絡跨過相鄰牌。還要檢查兩端算子的位置。任一端位於掩蔽標記下，使用這部無線電的條件就不成立。查的是算子與掩蔽標記的疊放位置。牌面印的地形值另計。"},
    {"from": 6, "to": 9, "title": "啟動前，先從上級沿傳令順序核對", "text": "地圖外營部先透過連部的營網 SCR300 啟動連部。跨集結牌聯絡兩個排部時，再檢查雙方 SCR536 與視線。連部與迫擊砲分隊已在 C0 同區，可直接用目視／口令。能通訊後仍須另花啟動或下令所需點數。"},
    {"from": 10, "to": 11, "title": "七種組合共用同一批備用算子", "text": "第 1 列四枚 PC A、第 2 列四枚 PC B 先入場，德軍留在供應區。抽到組合時得先確認配件夠、位置合法、能影響觸發牌。若所需算子已用完，重抽可放的組合，全無可放才算無接敵。標記和作戰算子適用的放置限制不同。"},
    {"from": 12, "to": 15, "title": "活動修正何時加在排部抽牌上？", "text": "手冊給設置與目標，接下來是網頁示例牌序。起始無接敵，所以連部與第 1 排的啟動抽牌各在大數字上加 1。連部每啟動一個排部花 1 點。輪到第 1 排時，班從與排部同區的 B0 出發，移入 PC 牌先標記暴露。"},
    {"from": 16, "to": 19, "title": "第 2 排的點數不能拿給第 1 排使用", "text": "第 22 號大數字 4 加無接敵 1，第 2 排有 5 點，可指揮在 D0 的所屬單位。兩排都啟動過，直接進一般主動。一般主動是全連另外抽的小數字，在本連級任務不減半，也不加無接敵修正。"},
    {"from": 20, "to": 22, "title": "用兩種隨機欄處理第一枚 PC", "text": "同級 PC 的順序與接敵後的組合是兩次不同判讀。四個候選先看 R#4 選 A1。無接敵時 PC A 自動接敵，再按第 48 頁 A 級表看 R#6。組合 1 直接在 A1 放生效來襲 −4，表上沒列觀測員，無須加算子。"},
    {"from": 23, "to": 25, "title": "第一枚處理完，下一枚就可能改抽七張", "text": "A1 上有友軍，來襲 VOF 讓活動立即升為接敵。因此接下來的 A 級不再自動，改為抽 7 張找 Contact。用來決定先後的那張只讀 RAND，其他圖示不作數。"},
    {"from": 26, "to": 28, "title": "一枚 PC 移除後，還要不要結算戰鬥？", "text": "每個待查位置都要完成自己的 7 張。未見 Contact，移除該處 PC 而不放組合。這不會消去別張牌先前放置的 VOF。A1 的友軍仍須結算來襲，本例第 1 號是 MISS，來襲仍留到下回合的火力任務更新。"},
    {"from": 29, "to": 30, "title": "新的回合要重查指揮鏈哪兩段？", "text": "先看 C0 連部是否仍有連接營部的 SCR300，再看兩排部與連部的 SCR536、視線與掩蔽。這個局面指揮部仍在原處，兩條件都成立。步兵班移出集結區，並未因此擁有連網電台。"},
    {"from": 31, "to": 34, "title": "命令點足夠，為何無法隔牌調動步兵班？", "text": "兩個排部仍在集結區，四個步兵班卻都已跨牌，而且沒有各自的通訊裝備。啟動排部取得點數，仍須另檢查它能否與受令班通訊。本例選擇放棄排部點數，等一般主動讓分散的班分別自行行動。"},
    {"from": 35, "to": 39, "title": "兩個排參與，不套用單排的減半", "text": "第 3 號牌左上小數字 4，連級演習可用全部 4 點，每個班自行花 1 點跨一張牌、標記暴露。四個班進入第 2 列後，B 級 PC 和友軍同牌，仍等到潛在接敵評估依序檢查。"},
    {"from": 40, "to": 42, "title": "為何第一枚 B 級又是自動？", "text": "火力任務更新先於 PC 評估。A1 的來襲一移除，棋桌已無 VOF、主要射向或已發現敵軍，活動回到無接敵。首枚 B 級自動接敵，改讀組合表 B 欄的 R#7。結果 2 在 A2 放一個已發現的小組。"},
    {"from": 43, "to": 47, "title": "重算活動時數地形牌，不數算子", "text": "A2 上敵我同牌，仍只算一張有人牌受 VOF，活動是接敵。剩餘 B 級 PC 因而各抽 5 張找 Contact。同級有多枚就為剩餘位置重新編號，最後一枚無須再抽順序。每次完成後移除該處 PC。"},
    {"from": 48, "to": 49, "title": "把通訊、PC 和目標一起核對", "text": "本課沿用第二次演習的兩個目標。八枚 PC 都已清除，地圖上已無敵軍作戰單位。回看你使用的兩種命令來源。兩個排部由連部通過連網啟動。後來遠離排部的四個班則使用一般主動點。下一次更改算子位置或裝備時，通訊條件也要隨局面重查。"},
  ],
  I1: [
    {"from": 0, "to": 1, "title": "命令點花在哪裡", "text": "把行動選單和棋桌並排看。命令點代表這個時段能要求單位做幾件事，每件事花掉的遊戲時間可以不同。算子看見已發現的敵軍且符合規則 §6.1 時會自動開火，此時直接更新主要射向（PDF）和火力量（VOF），命令軌不扣點。"},
    {"from": 2, "to": 2, "title": "目標達成後，回合還有什麼用", "text": "先查任務說明允許幾次嘗試。即使在再次嘗試的前幾回合便已確保目標，仍須維持到規定的最後一回合。例如一張敵方上級事件牌，可能使剛確保的目標再次受到挑戰。"},
    {"from": 3, "to": 4, "title": "先分清兩幅圖的目標", "text": "第 4 頁的規劃草圖寫著「10 回合、第 4 列、主要與次要目標」。下一節另設一張只有三列的練習桌，目標是第三列的農場。先核對任務文字，再到相應的圖上找目標標記，兩個例子的座標各自獨立。"},
    {"from": 5, "to": 6, "title": "從編制看指揮部能做什麼", "text": "準備時把排部的經驗、配屬算子、命令標記和起始位置一併核對。經驗會改變往後的命令抽牌，同區域的部署決定哪些算子可以目視／口令聯絡。第 5 頁提供的隊形是規劃範例，玩家可隨牌局調整。"},
  ],
  E1: [
    {"from": 0, "to": 2, "title": "配屬單位與三種無線電", "text": "先找 C3 的目標和集結區，再沿指揮關係讀資產。連部的 SCR300 聯絡圖外營部，SCR536 聯絡持有同網無線電的排部。觀測員的 SCR610 聯絡圖外支援。即使三者都畫作無線電，也要看使用哪個網路。"},
    {"from": 3, "to": 5, "title": "從啟動取得連部的第一筆命令", "text": "進攻方先行，首回合略過上級事件。圖外營部與連部的 SCR300 相通，可以啟動連部。連部這才抽牌看左上鋼盔內的大數字。牌值 5，一般經驗加 0、未接敵加 1、所在牌沒有火力量，命令軌記 6。"},
    {"from": 6, "to": 8, "title": "同一筆命令的三種用途", "text": "連部與 B0 的士官長同區域，可直接啟動。要啟動 C0 的排部，兩端須透過連網 SCR536。這兩次各用 1 點，再用 1 點讓同區域的 2/2 班跨牌移動並標暴露。從 6 點扣除 3 點後，把命令標記移到保留區的 3。"},
    {"from": 9, "to": 10, "title": "士官長為何也有自己的點數", "text": "士官長剛獲得啟動，輪到他的時段才抽牌。大數字 4、未接敵加 1、老兵加 1，得到 6 點。老兵在白晝最多可保留 9 點，本回合可花的上限是 6。他先花 1 點移到教堂，回到與 2/2 班可通訊的區域。"},
    {"from": 11, "to": 13, "title": "找 Cover 要看誰執行嘗試", "text": "先讀地形牌底部中央的抽牌數。一般經驗的 2/2 班在教堂翻 3 張找 Cover。若全落空，士官長花 1 點鼓舞只補 1 張。改由老兵士官長親自重新嘗試時，才是地形 3 張加老兵 1 張，共 4 張。"},
    {"from": 14, "to": 16, "title": "同張教堂牌為何還要花點移動", "text": "找出 Cover 的算子自動進入新掩蔽。都市掩蔽表本次給「堅固建築」，教堂塔樓另是一個最多容納 1 階的區域。士官長進入建築後失去與外面步兵班的直接通訊，因此先花 1 點出來，再花最後 1 點命令班進去。士官長留在外面。"},
    {"from": 17, "to": 20, "title": "排部能命令哪些算子", "text": "排部抽到大數字 6，新兵 −1 與未接敵 +1 抵消。這批所屬算子都在排部所在的集結區，可以接受目視／口令。1/LMG 離開牌後便超出這種通訊。分遣突擊組則是先從 3/2 班取下 1 階，在原牌建立 1 階小組，再另外付 1 點移動它。"},
    {"from": 21, "to": 23, "title": "一般主動可讓離開排部的單位行動", "text": "三枚指揮算子都已啟動，跳過各自的主動時段，再抽一般主動牌。鋼盔旁小數字 4 在單排任務減半為 2。可花 1 點使士官長與 2/2 班在建築內恢復直接通訊，再花 1 點讓不在排部身旁的 1/LMG 自行找掩蔽。"},
    {"from": 24, "to": 26, "title": "用 PC 標記決定是否發生接敵", "text": "只檢查同時有友軍單位和潛在接敵標記（PC）的牌。本次三張都為 A，先讀牌底 R#3 決定先後。果園先處理。當前「未接敵」使 PC A 自動生效，直接查任務組合表。條目中的斜線要求分牌、加號要求同牌。配置限制針對單位，照明等標記可以與既有敵軍同牌。"},
    {"from": 27, "to": 30, "title": "從組合表把算子放回地圖", "text": "分別取得兩組的方向，再照這個據點條目的距離欄判讀。R#10 得 1，落在 1–2，兩組因此各放在與果園相鄰的一張牌。敵軍尚未被發現，先將兩條 PDF 指向果園。果園記最強的 A 火力量及來自兩個方向的交叉火力，活動程度升為接敵。"},
    {"from": 31, "to": 33, "title": "為何一樣的 PC A 現在要抽七張", "text": "第一處接敵已經改變全圖的活動程度。剩下的農場和教堂同樣是 A，現在查「接敵」欄，每處須翻 7 張有效牌找 Contact。遇到重洗牌先繼續抽滿這一次，再把整副牌洗回。沒有 Contact 就移除該處 PC。"},
    {"from": 34, "to": 36, "title": "先看淨修正，再看命中影響幾階", "text": "果園突擊組的 A 火力量 −1、交叉 −1、暴露 −2、果園 +1，合計 −3。第一張查左側 −3 欄，得 HIT 才抽第二張。突擊組固定看一般經驗欄。CF 原可影響兩階，這個算子只有一階，因此只採第一個字母 C，換成傷亡。"},
    {"from": 37, "to": 37, "title": "為何到清理才轉動箭頭", "text": "同一戰鬥效果步驟的結果視為同時發生。到清理時才依新的棋局調整主要射向（PDF）和火力量（VOF）。傷亡算子已失去目標資格，墓園班轉向看得見且有 4 階的教堂。掩體內算子受射向限制，無其他適用目標便停火。暴露在此移除。"},
    {"from": 38, "to": 40, "title": "第二回合重新核對事件和保留點", "text": "從第二回合起，用上級指揮部無線電圖示檢查事件。連部仍可由營網啟動，這次大數字 3 加上保留 3 點得 6。活動已由未接敵升至接敵，先前的 +1 消失。連部經連網啟動第 2 排部，本回合未啟動士官長。"},
    {"from": 41, "to": 43, "title": "三枚移動算子共花幾點", "text": "觀測員、2/AT 組與連部由 B0 分別移至 B1，各自花 1 點、各自暴露。先前從 6 點中已花 1 點啟動排部，這三枚移完後剩 2 點。觀測員的 SCR610 隨他留在農場，之後才有條件處理支援任務。"},
    {"from": 44, "to": 45, "title": "兩種嘗試用不同的成功圖示", "text": "發現墓園班時先計算找準星的牌數。基本 2 張、在掩蔽下 −1、敵軍為 A 級 +1。成功後立即更新有視線單位的射向和活動程度。呼叫砲兵則依本任務給觀測員的額度翻 2 張找爆炸圖示。成功先放「待發」，並把可用任務從 4 記為 3。"},
    {"from": 46, "to": 49, "title": "排部的保留上限與幕僚的主動點", "text": "排部的大數字 4 減新兵 1、加上回合保留 3，共 6。移動 1/2 班後還有 5 點，新兵最多只能帶走 3 點。未啟動的連士官長輪到幕僚主動時段，直接得到 1 點。他與 2/2 班同在教堂建築內，可用這點讓班作集中射擊嘗試。"},
    {"from": 50, "to": 52, "title": "只有發現嘗試保證至少一張", "text": "一般主動的小數字 4 減半為 2，遠在 D1 的 1/2 班可以使用。發現嘗試從基本 2 張算起，敵在掩蔽 −1、A 級 +1，所以仍翻 2 張找準星。發現嘗試保證修正後至少翻 1 張。其他嘗試若減到 0 張就不能做。"},
    {"from": 53, "to": 54, "title": "榴彈未命中為何還要放標記", "text": "槍榴彈是 1/2 班的一次性資產，無論這 2 張是否翻到榴彈圖示都會用盡。本次掩體牌已有 S 火力量，未命中標記使同牌所有單位的淨修正各減 1。若牌上只有榴彈未命中，它本身便作為實際火力量，同牌所有單位皆受影響。"},
    {"from": 55, "to": 58, "title": "順序、情況與任務欄各查一次", "text": "先看敵方事件圖示，再以 R#2 選出兩張敵軍牌的檢查順序。在活動優先表自上而下找第一個適用情況，再讀任務的「周密防禦」欄。墓園班因此轉移 PDF，掩體的兩枚單位則各自受掩體與戰術欄限制，這次沒有合法行動。"},
    {"from": 59, "to": 60, "title": "待發翻面後，要重新查視線與 PC", "text": "在火力任務更新步驟才把 B2 的「待發」翻到「來襲」。墓園班失去對牌外視線，應撤掉它對農場的射向。本回合已射擊的耗彈仍須記錄。接著輪到 D1 的 PC A，此時兩張有單位的牌受火力影響，查「交戰」欄翻 5 張找 Contact。"},
    {"from": 61, "to": 63, "title": "最強火力量只算一次，各枚算子各抽一次", "text": "墓園採來襲 −5，加地形 +1、戰壕 +2、交叉 −1，總和 −3。不再把較弱的 A 疊加進去。掩體兩枚算子各是地形 +2、掩體 +3、S +0、榴彈未命中 −1，合計 +4。即使總和一樣，班和重機槍仍各翻一張。"},
    {"from": 64, "to": 65, "title": "兩回合示範在什麼局面收尾", "text": "清理移除暴露和榴彈未命中。受壓制及生效中的來襲各有自己的移除時機，所以兩者留到下一回合。C3 仍待確保。若續玩，用諾曼第任務 1 的組合表。遇到算子不足以完整放出組合，依這個範例的特則直接移除 PC。"},
  ],
  V1: [
    {"from": 0, "to": 3, "title": "先從任務卡找出本局的例外", "text": "五回合內要確保的是 B3。手冊只帶玩家走前兩回合。地圖上已有被發現的德軍，活動程度從「接敵」開始，只有 C2 戰壕算子起初未被發現。兩方都略過事件，一般主動按單排規模減半並向下取整。彈藥要依各算子分開記帳。"},
    {"from": 4, "to": 8, "title": "連部為何能啟動兩個不同位置的指揮部", "text": "營部啟動連部後，鋼盔大數字給連部 5 點。B0 的排部和連部同區域，可直接通訊。A0 的戰車指揮部則與連部透過 SCR300 和營戰術網聯絡。兩次啟動共花 2 點，留下 3 點。輪到排部時，才抽它自己的 6 點。"},
    {"from": 9, "to": 11, "title": "兩枚算子同進村莊，暴露狀態卻不同", "text": "1/LMG 普通移動跨到 C1，放暴露並立刻更新火力量。第 1 排部花自己的下一點作滲透嘗試。翻 2 張成功，這次跨牌移動免放暴露。現在兩枚算子又在村莊同一區域，排部可直接命令 1/LMG。"},
    {"from": 12, "to": 15, "title": "建築的發現者與後來進入者", "text": "1/LMG 翻 4 張找 Cover。本任務規定都市掩蔽一律為堅固建築，所以成功後它直接進入，排部另花 1 點跟進並標暴露。兩者同區域後，1/LMG 可以接受發現命令。從基本 2 張減去目標掩蔽 1，先翻 1 張找準星。鼓舞再花 1 點，只補 1 張。"},
    {"from": 16, "to": 20, "title": "先登記車輛已啟動，稍後才移車", "text": "先讀戰車指揮部啟動命令的大數字 5。每花 1 點，就給一輛車放一枚「已啟動」標記，讓它在稍後的車輛階段有行動資格。12 至 15 號共用 4 點，餘下 1 點移入保留區。現在所有車輛都還在集結區。"},
    {"from": 21, "to": 23, "title": "發現成功的當下就更新箭頭", "text": "三個指揮部都已啟動，只剩一般主動可用。小數字 4 在這個小規模任務換為 2 點。1/LMG 用第一點再找準星，成功後雙方的 PDF 相對，活動升為交戰。1/1 班用第二點到果園，另一張牌也指向同一敵軍，才加交叉火力。"},
    {"from": 24, "to": 25, "title": "活動表的「不行動」影響哪個時段", "text": "先在敵軍活動階段查看適用的活動表項目。火箭筒組這次抽到 1 而沒有活動表行動，但本任務仍讓未受壓制的反戰車算子每回合啟動。到車輛階段輪到已啟動的敵步兵時，只要有合法的反戰車射擊就執行。移動途中觸發的反應另行處理。"},
    {"from": 26, "to": 27, "title": "移到新牌，先讀地形和基本火力量", "text": "車輛移動會依序檢查出發牌、進入的新牌及其反應，進入 SLOW 地形便在該牌停下。雪曼 15 到村莊先結算 S 火力量。表列修正 +3，移動 +1，村莊 +3，車輛防禦 +0。再加行動牌反戰車值 +7，總和 +14 為未命中。"},
    {"from": 28, "to": 30, "title": "G! 需要兩次不同的牌面判讀", "text": "C2 算子的 G! 表示先翻 2 張找榴彈圖示，出現後才另翻一張，讀反戰車值。本例淨修正 +2 加牌值 0，結果「撤退」，把雪曼 15 移出本局。C2 算子耗 1 點彈藥，放已移動／射擊。接下來雪曼 14 入村時，它已不能在這個階段再反應。"},
    {"from": 31, "to": 32, "title": "車輛階段結束後仍要結算步兵", "text": "戰鬥效果要對受火力量的步兵算子各查一次。火箭筒組查 0 欄，村莊內的 1/LMG 與排部各查 +4 欄。同欄可以抽到不同結果。清理時才移除已啟動、已移動／射擊和暴露。受壓制保留，因而改變下一回合村莊所受的 VOF。"},
    {"from": 33, "to": 36, "title": "留在建築內，仍可透過野戰電話啟動", "text": "連部抽到 4，加上回合的 3 點保留，命令軌記 7。村莊排部攜帶 EE8，電話線仍連著相鄰的連部，即使在建築掩蔽內也能通訊。連部分別用電話與營網啟動兩個指揮部，將餘下 5 點保留。排部另抽自己的 6 點。"},
    {"from": 37, "to": 41, "title": "鼓舞只補一張，失敗後壓制仍在", "text": "排部花 1 點讓 1/LMG 重整，翻 2 張找 Rally。再花 1 點鼓舞，只能為剛才的失敗補 1 張。兩次都落空，機槍組繼續受壓制。排部移往果園後可直接向同區域的 1/1 班下令。排部自己找到的基本掩蔽 +1 留在果園。"},
    {"from": 42, "to": 46, "title": "戰車指揮車也需要自己的啟動標記", "text": "戰車指揮部以大數字 4 加保留 1，共 5 點，可經本排車輛網分配命令。這次 12、13、14 號與 11 號指揮車都要在車輛階段行動，所以連指揮車自己也要花 1 點啟動。四枚標記共花 4 點，剩 1 點保留。"},
    {"from": 47, "to": 49, "title": "同一枚步兵班可分別使用兩點一般主動", "text": "讀小數字 4，依任務規模折半成 2。1/1 班先用 1 點翻 3 張找 Cover，成功後依都市特則進入堅固建築。再用 1 點翻 2 張找集中射擊的準星。第二次失敗不會取消先前找到的掩蔽。"},
    {"from": 50, "to": 53, "title": "活動表要對每枚算子的現況重新查", "text": "B3 受火力且在掩蔽外，A3 未受火力但 PDF 上有目標，兩者分別查到集中射擊，各翻 2 張找準星。C2 算子已受壓制，改查受壓制優先序，結果 4 為後退。它離開 C2 後撤掉它對村莊的火力量，村莊原來指向 C2 的箭頭仍然保留。"},
    {"from": 54, "to": 55, "title": "一次車輛移動可以經過不只一張牌", "text": "以 14 號為例，出發後先進 B1。這一步沒有適用的基本火力量或反應，可繼續同一次移動。進到 A2 就要重新檢查該牌，並因 SLOW 在此停下。若兩枚算子都能反應，第一個結果可能讓第二次失去目標，所以要隨機定先後。"},
    {"from": 56, "to": 57, "title": "擊毀後為何還要再翻兩張", "text": "本次反應在牌表上的淨修正為 −2，加行動牌的 +2 得 0，將 14 號換成殘骸。車輛表列有兩階車組，因此以新兵欄各判一階，L 成為受壓制擔架組、C 成為傷亡。結果 0 同時符合該砲算子的快速射擊條件，此次不放已移動／射擊。"},
    {"from": 58, "to": 62, "title": "下一枚車進同一張牌，也要重新結算", "text": "雪曼 12 經果園進 A2，重新判定反應順序。先前取得快速射擊資格的 88 公釐砲算子還可參加。這次依序讀行動牌的 +7、+9，兩次都未命中，耗彈並標已移動／射擊。13 號和指揮車移入果園後，這個車輛階段才結束。"},
    {"from": 63, "to": 64, "title": "為何現在可以不抽 Rally 就解除壓制", "text": "輪到戰鬥階段的壓制恢復步驟，逐枚檢查受壓制算子所在牌的有效 VOF。村莊的 1/LMG 和 C3 的火箭筒組都已脫離影響，直接移除壓制。這個自動步驟和先前花命令點、抽 Rally 嘗試的重整各有時機。"},
    {"from": 65, "to": 67, "title": "戰鬥效果、耗彈與任務目標分開記錄", "text": "B3 的兩階砲算子在本次命中效果讀到 A。本體剩一階、同牌出現一階突擊組，兩者皆受壓制。它本回合仍曾提供 VOF，須另記一次耗彈。清理後農場受 S 火力量影響。現在只完成手冊的第二回合，五回合內確保 B3 仍是任務目標。"},
  ],
  V2: [
    {"from": 0, "to": 3, "title": "任務二改寫了 PC 接敵的結果", "text": "第一列三張牌各放一枚 PC A，逐張保留到有適用單位時才檢查。若發生接敵，按本任務直接取一輛已被發現、具有 5 點彈藥的敵方 M5，在第三列隨機配置。若抽到通行性為 NO 的地形，才改用第二列最左或最右的牌。"},
    {"from": 4, "to": 5, "title": "先分行動組別，再讀中盤圖", "text": "本任務指定雙方車輛先完成行動，再輪到雙方有反戰車能力的步兵。途中的反應仍在移動當下結算。第 25 頁另給一幅「幾回合後」的局面，所以切到該圖時，原火箭筒組已成擔架組，右上已有一輛敵方 M5。"},
    {"from": 6, "to": 9, "title": "受壓制車輛如何判讀起始牌與到達牌", "text": "受壓制的雪曼 12 仍可選移動。先在起始牌算 S +3、防禦與地形各 0、受壓制 −1，得 +2，再加牌值 +6 是 +8，未命中。進村後牌上的 P 無效果，另判反應。淨修正 −4 加牌值 +1 為 −3，查得爆燃。放燃燒殘骸和兩階傷亡，煙霧隨即改變牌外視線。"},
    {"from": 10, "to": 12, "title": "敵 M5 依任務優先表行動", "text": "我方動完一枚，換敵方車輛組。M5 當下看不見美軍戰車，往下查有指揮部的牌。手冊中兩種路徑同等，抽定進果園。到達後適用的 S 火力量也可來自同方。S +3、地形 +1、移動 +1、M5 防禦 −1，得 +4，再加牌值 +3 為 +7。"},
    {"from": 13, "to": 15, "title": "普通殘骸與燃燒殘骸的車組結果", "text": "戰車指揮部的反應用另一張牌。本次淨修正 +1 加牌值 0，查得「擊毀」。用一般殘骸替換 M5，再翻命中效果判車組。本次 L 對應受壓制擔架組。這與稍早雪曼 12 的「爆燃」直接留下兩階傷亡不同。"},
    {"from": 16, "to": 19, "title": "同一張牌的不同火力量來源要分清", "text": "13 號進教堂時，具反戰車能力的 H、A 級單位不以自身基本 VOF 結算車輛，所以此處只算輕機槍的 A。步兵砲算子的 G! 另翻基本 2 張加本例修正 1 張，出現榴彈圖示才讀反戰車值。最後一點彈藥用盡便翻成火力組。等下回合後退至視線外，才標未被發現。"},
    {"from": 20, "to": 21, "title": "用殘骸判斷這個階段能否繼續", "text": "B3 的燃燒殘骸持續到任務結束，煙霧使同牌的 88 公釐砲算子失去對牌外的視線。即使排到它的行動，這次也沒有合法目標。車輛階段結束後，擔架組所受 VOF 留到戰鬥效果步驟，75 公釐砲的 PDF 則在清理時更新。"},
  ],
  D1: [
    {"from": 0, "to": 0, "title": "哪六張牌算進勝利條件？", "text": "先在地圖上找出主抵抗線後方的兩列，共 12 張牌。任務結束時，每張要同時有友軍算子、沒有敵軍算子，才算「確保」。其中至少 6 張要符合。經驗表還會替其他成果計分，所以達成勝利條件和算出經驗點是兩道不同的結算。"},
    {"from": 1, "to": 2, "title": "編制表告訴你拿哪些算子，配屬表決定誰能下令", "text": "三門 60 公釐迫擊砲在棋桌上合為一枚三階算子，三門 57 公釐則各有一枚。把武器排與任務增配的算子按第 29 頁登記到各排。特別留意三枚重機槍，本例將它們留在一般支援欄，由連部或連部幕僚下令。"},
    {"from": 3, "to": 4, "title": "在持有人格內記下資產與約定信號", "text": "拿到電話的單位才有這項通訊資產。六部 EE8 中，連部、副連長、三個排部各得一部，第六部給迫擊砲分隊。信號還要登記用途，本例的連部降落傘信號用於 FPL、FPF，副連長的紅星集束才是全體停火。指揮顯示表能讓你在需要時查到持有人。"},
    {"from": 5, "to": 6, "title": "主抵抗線和傷亡收集點各管什麼？", "text": "主抵抗線（MLR）橫跨第 2、3 列之間。事件可使它移動，突擊組可越線到緊貼這條線的一列（第 33 頁）。傷亡收集點（CCP）位置由玩家依本戰役規則選擇，可選正面地形牌或集結區，這次選 D0。"},
    {"from": 7, "to": 10, "title": "先找任務計分的牌，再讀部署圖", "text": "第 1、2 列共 12 張，本例每張放兩個散兵坑，合計 24 個。到了任務結束，還要檢查每張牌是否有友軍佔據且無敵軍，才知道幾張算作「確保」。讀第 32 頁時，藍框是第 1 排、紅框是第 2 排、綠框是第 3 排，每一色都有前線與預備兩組位置。這是作者為本次任務選的配置。"},
    {"from": 11, "to": 12, "title": "FPL 箭頭上的 H 何時生效？", "text": "先看機槍算子的火力量上方有沒有箭頭，有才可配最後防護線（FPL）標記。配置後它會等連部發出約定信號，屆時沿標記斜箭頭施加 H 火力量。若改下「轉移射擊」命令，移除 FPL，恢復依該牌的正常主要射向處理（§7.2.4）。"},
    {"from": 13, "to": 13, "title": "FPF 標記放的是目標牌", "text": "前兩枚 FPL 和機槍算子疊放。現在拿的 FPF 代表砲兵最後防護射擊，要放在連部或合格觀測員看得到的目標地形牌。作者選的是第 3 列第 5 欄 E3。放下標記只確定目標，之後仍需啟動。"},
    {"from": 14, "to": 14, "title": "連部在 D0，如何連上各排？", "text": "集結區牌彼此已有電話連線，也能接到第 1 列的電話或線路。對照第 32 頁黃虛線，清點四枚電話線標記，其中三枚在 A1、C1、E1，一枚留在連士官長資產格。遊戲事件可能使線路中斷，屆時要重查通訊（§4.3.4）。"},
    {"from": 15, "to": 16, "title": "防禦回合為何先看敵軍活動？", "text": "防禦採流程 3.2，敵軍先行，之後才輪友軍指揮。第一回合略過雙方上級事件，起始圖上也沒有 PC。到敵軍活動檢查步驟開頭，依任務時程表的第 1 回合欄，在第 1、2 列每張各放一枚 C 型。"},
    {"from": 17, "to": 18, "title": "放上 PC 與判定 PC 是兩個時點", "text": "時程表還要求第 3 列各放一枚 B 型。它們只表示潛在接敵。本例第 3 列暫無美軍，擺上時也不抽敵軍。先接友軍指揮，到潛在接敵判定步驟再檢查美軍佔據的牌，最後在清理階段移除未觸發標記。"},
  ],
  H1: [
    {"from": 0, "to": 1, "title": "任務編制如何影響後面的裝載表？", "text": "任務書准許在 81 公釐迫擊砲分隊與第 4 排之間選擇。手冊選第 4 排，60 公釐組配屬該排。另把空中管制員、砲兵觀測員、迫擊砲觀測員依序記入第 1、2、3 排。這三枚各一階，也要占用稍後的裝載空間。"},
    {"from": 2, "to": 3, "title": "從兵力階的 V、L、G 算出整枚算子的經驗", "text": "先分出指揮部與配屬單位已指定的等級。其餘可分配的 39 階中，V 老兵 7 階、L 一般 18 階、G 新兵 14 階。三階班若分到 VVL，查「多階單位經驗等級」表得到老兵。LLG 則是一般。設置完成後只追蹤整枚算子的等級。"},
    {"from": 4, "to": 5, "title": "同是資產，怎麼知道它提供通訊還是命令？", "text": "10 部連戰術無線電先給七個指揮部與幕僚，剩下三部給 2/1、2/2、1/3 三個一般班。手冊的理由是這些班可藉通訊分開行動，老兵班則比較能靠自己的主動行動。另把本例的兩枚紅色星號信號登記成一次性停火命令。彩色煙霧還可標記替代著陸區。"},
    {"from": 6, "to": 7, "title": "中央地形牌必須能當著陸區", "text": "請看 C3 地形牌右下角的直升機圖示。正式設置若抽到不合格的中央牌，可以和已翻開且有圖示的地形牌交換，或棄掉重抽。確定牌面合格後放主要著陸區（LZ）標記。本任務指定這是無敵情 LZ，所以中央不放 PC。"},
    {"from": 8, "to": 9, "title": "為什麼圖上有 24 枚問號，目標卻是清除 12 張？", "text": "把 A、B、C 型 PC 都翻成問號再隨機抽取，其他 24 張牌各得一枚，連外圈朝下的地形也要放。任務結束時，只算開局有 PC、現在已無 PC 且無敵軍的牌，無須有友軍留下。中央 LZ 一開始沒有 PC，因此不能貢獻這 12 張。"},
    {"from": 10, "to": 10, "title": "規劃卡的容量用兵力階計算", "text": "全連連同三名觀測配屬共 48 階。12 架 UH-1 各載 3 階，兩架 CH-47 各載 12 階，總容量是 36＋24＝60 階。雖然總數夠，每個機位仍有自己的上限。若一枚班算子放不進去，可分遣一階小組，把兩部分記在不同機位。"},
    {"from": 11, "to": 14, "title": "第一波示範兩種剛好三階的組合", "text": "無敵情 LZ 讓作者選擇在第一波裝入連部、空中管制員及砲兵觀測員。對照第 38 頁，11、12 號格各有三枚一階算子。13、14 號格各只有一枚三階班。四格都剛好三階，算子枚數卻不同。"},
    {"from": 15, "to": 18, "title": "第二波的「一枚班」只占兩階", "text": "看規劃圖上的班算子兵力，再核對同格的另一枚算子。21 至 24 號每架都是二階班加一階的指揮部、觀測員或武器組，合計三階。譬如 21 號是第 2 排部一階加 3/2 班兩階。已分遣出去的一階在另一個機位另算。"},
    {"from": 19, "to": 22, "title": "分遣的小組也要登記機位", "text": "31 號的第 3 排部、1/W/3 與突擊組各一階。32 號是一階武器組加二階 1/3 班，33、34 號各裝一個三階班。到此前三波共裝 36 階。分遣出的突擊組有自己的算子，著陸後可補入班，也可保持獨立。"},
    {"from": 23, "to": 24, "title": "第四波有空位，示例為何仍分兩架？", "text": "前面裝了 36 階，48－36＝12 階待裝，一架 CH-47 就能載完。作者把 12 階分成每架六階，分別記在 41、42 號格，避免一次航空器損失判定就牽連整波。每架容量仍是 12 階，本次各用了六階。"},
    {"from": 25, "to": 26, "title": "把飛機移到管制卡，乘員仍看規劃卡", "text": "規劃卡記錄每架搭誰，管制卡記錄這一波現在在哪裡。第 1 波已在進場格等第一回合，第 2 波還在接載區。排定波次依第 11 節沿格自動推進，不花連部命令。若事件另外在接載區放了彈藥，該次運入才另需連部啟動命令和彩煙。"},
    {"from": 27, "to": 27, "title": "開始前為何要準備隨機抽取杯？", "text": "三種越共班以抽杯決定，抽出後要核對該算子有沒有一次性 RPG。依戰役特殊規則 5 的隧道例外，由某張牌觸發的 PC 可能將敵軍放到另一張有友軍的牌上。把這些規則和杯子準備好，本章就停在第一波進圖之前。"},
  ],
  R1: [
    {"from": 0, "to": 1, "title": "下一個任務從這一局留下的人員開始", "text": "先對照第 40 頁出發時的編制，以及第 42 頁第十回合結束後的算子。把棋桌與指揮顯示表上的正常單位、小組和傷亡按兵力階相加，連三個配屬都算在起始的 48 階內。通過核對後，才能判斷哪些算子可以重組、哪些缺口得等補充。"},
    {"from": 2, "to": 3, "title": "一階小組能重組，一階傷亡要等補充", "text": "5 個癱瘓組＋3 個擔架組＋3 個火力組＋3 個突擊組，共 14 階，任務之間都視作新兵。它們可用來重建任何適用的連隊單位，無須追原屬班。另有 10 階傷亡，已後送的 5 階仍包含在這 10 階裡。兩類合計有 24 階受影響。"},
    {"from": 4, "to": 6, "title": "沿任務經驗表逐項計算，再合併", "text": "14 張清除牌中，前十張各計 1 點，接下來四張各計 2 點，合計 10×1＋4×2＝18。敵方損失的 5 階已含俘虜，只把兩階俘虜各加的一點另算，得到 7。再加兩次成功判定的 2 點，以及後送 5 階各得 2 點的 10 點，這次可分配 18＋7＋2＋10＝37 點。"},
    {"from": 7, "to": 8, "title": "區分戰役輪調與重組資格", "text": "越南戰役先讓兩階老兵返鄉，玩家可自己選。作者選連士官長與 1/W/3，讓第 1 排的老兵機槍留隊。第 1 排部可用一階小組免費重組，但新重組的指揮部或幕僚本輪必須維持新兵。把經驗點留給可晉升的人。"},
    {"from": 9, "to": 10, "title": "費用按每階目前的等級決定", "text": "原來就在編制裡的連部和第 2、3 排部都是新兵，各花 1 點升一般。副連長、第 4 排部與迫擊砲組都是一般，各花 3 點升老兵。兩筆共 3＋9＝12 點，37 點還剩 25。同一兵力階在這次程序最多升一級。"},
    {"from": 11, "to": 13, "title": "逐階付費，再查班的整體等級", "text": "重組一階免費，只有晉升才扣點。2/1 的兩階一般各花 3 點升老兵，再替重組的一階新兵花 1 點升一般，共 7 點，查表 VVL 為三階老兵班。3/1 則只把兩階升一般，第三階留新兵，LLG 已足以成為一般班。"},
    {"from": 14, "to": 16, "title": "算出整班的等級，才能衡量每一點的用途", "text": "第 2 排先用 2 點，分別把重組的機槍與 1/2 班的第三階升一般。2/2 剩的兩階各付 3 點升老兵，3/2 的兩階各付 1 點升一般，再扣 8 點。剩 4 點交第 3 排。重組 1/3 的三階後只升其中兩階，整班同樣能登記為一般。"},
    {"from": 17, "to": 18, "title": "重組允許不同方案，經驗用盡仍可重組", "text": "2/3、3/3 各剩一階。作者用最後 2 點把兩階升一般，合成一個二階 2/3 班。也可各保留一個一階火力組，等補充後再各組成班。第 4 排把 1/4 殘餘一階免費重組為火力組。三個觀測配屬歸營部處理，下一任務重新準備。"},
    {"from": 19, "to": 21, "title": "先處理越南輪調，再填空缺", "text": "越南每任務後補 6 階新兵，再依傷亡每滿 4 階補 1 階老兵。10 階傷亡得到 2 階老兵。規則另要求用一階新兵替換一個一般或老兵排部，作者換第 3 排部。這次替換沒有填補缺口。連士官長是空缺，新幕僚一律新兵，配給老兵也不會保有老兵等級。"},
    {"from": 22, "to": 23, "title": "相同的一階補充，放入不同單位會改變結果", "text": "1/1 的兩階已是一般，加一階新兵仍是三階一般班。相反，2/2 的兩階是老兵，若補新兵查表會降為一般，作者因此將最後一階老兵留給 2/2，再用新兵補 2/W/2。新來的補充在同次程序不能花經驗點晉升。"},
    {"from": 24, "to": 25, "title": "把缺額一併帶進下一個任務", "text": "最後兩階新兵分給 2/3 和 1/4，分別成為三階一般班與二階新兵班。核對缺額時，換完排部還有 11 階空缺，其餘七階補充都填入空位，11－7＝4。第 3 排留下的三階 3/3 班與一階 1/W/3 機槍組，正好對上這四階。"},
  ],
};
